`buildRows()` in `[report.js](src/report.js)` already returns the plain data — no change needed there.

```js
// cli.js
function main(argv) {
  const command = argv[0];
  if (command !== 'report') {
    process.stderr.write(USAGE + '\n');
    return 1;
  }
  const json = argv.includes('--json');
  const rows = buildRows();
  process.stdout.write(json ? JSON.stringify(rows, null, 2) : toTable(rows));
  process.stdout.write('\n');
  return 0;
}
```

